// ── source: vcx/tests/bigint_overflow_test.v ──
// Pass-2 D-H — over-i64 integer handling.
//
// Ruling: a BARE decimal integer that overflows i64 AUTO-PROMOTES to bigint
// (stays numeric) in BOTH the data and program readings; an EXPLICIT `::int`
// (or sized-int) overflow is a HARD ERROR (CXER0290 / CXERLEX-RANGE), never a
// silent clamp/wrap. The near-boundary case (i64 max + 1) must promote too —
// V's parse_int silently CLAMPS it, which parse_i64_checked guards against.

const over_i64 = '99999999999999999999999999999' // 29 digits, far over

const max_plus_1 = '9223372036854775808'          // i64 max + 1 (clamp trap)

const i64_max = '9223372036854775807'

const i64_min = '-9223372036854775808'

// ── Data reading ─────────────────────────────────────────────────────────────

fn scalar_of(src string) cx.ScalarNode {
	doc := cx.parse(src) or {
		assert false, 'parse failed: ${err}'
		return cx.ScalarNode{}
	}
	el := doc.elements[0] as cx.Element
	return el.items[0] as cx.ScalarNode
}

fn test_data_bare_overflow_promotes_to_bigint() {
	s := scalar_of('[n ${over_i64}]')
	assert s.data_type == .bigint_type, 'expected bigint, got ${s.data_type}'
	assert (s.value as string) == over_i64, 'bigint value mismatch: ${s.value}'
}

fn test_data_near_boundary_promotes_to_bigint() {
	// i64 max + 1 must NOT clamp to max — it promotes to bigint.
	s := scalar_of('[n ${max_plus_1}]')
	assert s.data_type == .bigint_type, 'max+1 should be bigint, got ${s.data_type}'
	assert (s.value as string) == max_plus_1, 'value mismatch: ${s.value}'
}

fn test_data_i64_max_stays_int() {
	s := scalar_of('[n ${i64_max}]')
	assert s.data_type == .int_type, 'i64 max should stay int, got ${s.data_type}'
	assert (s.value as i64) == i64(9223372036854775807), 'value mismatch'
}

fn test_data_explicit_int_overflow_errors() {
	if _ := cx.parse('[n::int ${over_i64}]') {
		assert false, 'expected CXER0290 for ::int overflow'
	}
}

fn test_data_explicit_int_i64_min_ok() {
	// The asymmetric boundary: |i64 min| overflows when read positive, but
	// -9223372036854775808 is a valid i64.
	s := scalar_of('[n::int ${i64_min}]')
	assert s.data_type == .int_type, 'i64 min should be int, got ${s.data_type}'
	assert (s.value as i64) == i64(-9223372036854775808), 'value mismatch: ${s.value}'
}

fn test_data_explicit_int_leading_zero_ok() {
	// Explicit ::int bypasses the leading-zero auto-typing rule: 02134 → 2134.
	s := scalar_of('[n::int 02134]')
	assert s.data_type == .int_type, 'expected int, got ${s.data_type}'
	assert (s.value as i64) == i64(2134), 'value mismatch: ${s.value}'
}

// ── Program reading ──────────────────────────────────────────────────────────

fn test_program_bare_overflow_promotes_to_bigint() {
	out := code.eval_code('', over_i64, 'json') or {
		assert false, 'eval failed: ${err}'
		return
	}
	assert out.contains('"dataType":"bigint"'), 'expected bigint result, got: ${out}'
	assert out.contains(over_i64), 'bigint value missing: ${out}'
}

fn test_program_near_boundary_promotes_to_bigint() {
	out := code.eval_code('', max_plus_1, 'json') or {
		assert false, 'eval failed: ${err}'
		return
	}
	assert out.contains('"dataType":"bigint"'), 'max+1 should be bigint, got: ${out}'
}

fn test_program_bigint_renders_bare() {
	// A bigint result renders WITHOUT quotes in canonical CX (it is numeric).
	out := code.eval_code('', over_i64, 'cx') or {
		assert false, 'eval failed: ${err}'
		return
	}
	assert out.trim_space() == over_i64, 'bigint should render bare, got: ${out}'
}

fn test_program_explicit_int_overflow_errors() {
	if _ := code.eval_code('', '[n::int ${over_i64}]', 'cx') {
		assert false, 'expected CXER0290 for program ::int overflow'
	}
}

// ── source: vcx/tests/datetime_test.v ──
// Phase 7.74c-datetime-foundations — strict-cell datetime wire form.
// Covers parse_iso_datetime_canonical edge cases, format_iso_datetime_utc
// reconstruction, and chunked-table strict-cell datetime round-trip.
// Spec: spec/core/data-bin.md §3.6.1.
// ── parse_iso_datetime_canonical ─────────────────────────────────────────────

fn test_parse_iso_datetime_zulu() {
	ns, off := cx.parse_iso_datetime_canonical('1970-01-01T00:00:00Z') or {
		panic('parse failed: ${err}')
	}
	assert ns == 0, 'expected ns=0 for Unix epoch; got ${ns}'
	assert off == 0
}

fn test_parse_iso_datetime_positive_offset() {
	// 2024-01-15T12:34:56+05:30 = local 12:34:56, UTC 07:04:56
	ns, off := cx.parse_iso_datetime_canonical('2024-01-15T12:34:56+05:30') or {
		panic('parse failed: ${err}')
	}
	// UTC equivalent string:
	round := cx.format_iso_datetime_utc(ns, 0)
	assert round == '2024-01-15T07:04:56Z', 'got ${round}'
	assert off == i16(330)
}

fn test_parse_iso_datetime_negative_offset() {
	// 2024-01-15T12:34:56-08:00 = UTC 20:34:56
	ns, off := cx.parse_iso_datetime_canonical('2024-01-15T12:34:56-08:00') or {
		panic('parse failed: ${err}')
	}
	round := cx.format_iso_datetime_utc(ns, 0)
	assert round == '2024-01-15T20:34:56Z', 'got ${round}'
	assert off == i16(-480)
}

fn test_parse_iso_datetime_naive_treated_as_utc() {
	ns, off := cx.parse_iso_datetime_canonical('2024-01-15T12:34:56') or {
		panic('parse failed: ${err}')
	}
	round := cx.format_iso_datetime_utc(ns, 0)
	assert round == '2024-01-15T12:34:56Z', 'got ${round}'
	assert off == 0
}

fn test_parse_iso_datetime_fractional_seconds() {
	ns, _ := cx.parse_iso_datetime_canonical('2024-01-15T12:34:56.123456789Z') or {
		panic('parse failed: ${err}')
	}
	round := cx.format_iso_datetime_utc(ns, 0)
	assert round == '2024-01-15T12:34:56.123456789Z', 'got ${round}'
}

fn test_parse_iso_datetime_fractional_truncates_beyond_ns() {
	// 12 digits after dot → truncate to 9.
	ns, _ := cx.parse_iso_datetime_canonical('2024-01-15T12:34:56.123456789012Z') or {
		panic('parse failed: ${err}')
	}
	round := cx.format_iso_datetime_utc(ns, 0)
	assert round == '2024-01-15T12:34:56.123456789Z', 'got ${round}'
}

fn test_parse_iso_datetime_fractional_pads_ns() {
	// 3 digits after dot → 0.123 s → 123_000_000 ns.
	ns, _ := cx.parse_iso_datetime_canonical('2024-01-15T12:34:56.123Z') or {
		panic('parse failed: ${err}')
	}
	round := cx.format_iso_datetime_utc(ns, 0)
	assert round == '2024-01-15T12:34:56.123Z', 'got ${round}'
}

fn test_parse_iso_datetime_pre_epoch() {
	// 1969-12-31T23:59:59Z = -1 second from epoch.
	ns, _ := cx.parse_iso_datetime_canonical('1969-12-31T23:59:59Z') or {
		panic('parse failed: ${err}')
	}
	assert ns == i64(-1_000_000_000), 'expected -1e9 ns; got ${ns}'
	round := cx.format_iso_datetime_utc(ns, 0)
	assert round == '1969-12-31T23:59:59Z', 'got ${round}'
}

fn test_parse_iso_datetime_rejects_leap_second() {
	cx.parse_iso_datetime_canonical('2024-06-30T23:59:60Z') or {
		assert err.msg().contains('leap'), 'expected leap-second error; got ${err.msg()}'
		return
	}
	assert false, 'expected error on leap second'
}

fn test_parse_iso_datetime_rejects_bad_month() {
	cx.parse_iso_datetime_canonical('2024-13-01T00:00:00Z') or { return }
	assert false, 'expected error on month 13'
}

fn test_parse_iso_datetime_rejects_malformed() {
	cx.parse_iso_datetime_canonical('not-a-datetime') or { return }
	assert false, 'expected error on malformed input'
}

// ── chunked-table strict-cell datetime round-trip ────────────────────────────

fn test_chunked_datetime_column_round_trip() {
	src := '[evts [table[name::string when::datetime]]
  alpha 2024-01-15T12:34:56Z
  beta  2025-06-30T23:00:00+02:00
  gamma 2023-12-25T08:15:30.250Z
]'
	doc := cx.parse(src) or { panic('parse failed: ${err}') }
	bytes := cx.emit_data_bin_chunked(doc, cx.ChunkedEmitOptions{ chunk_size: 4, compress: .never }) or {
		panic('chunked emit failed: ${err}')
	}
	doc2 := cx.parse_data_bin(bytes) or { panic('decode failed: ${err}') }
	cx_out := cx.emit_cx(doc2)

	// Names round-trip; the offset RIDES the transport (#807(d), RULED
	// arc-2 — packet §10): unix_nanos is UTC-normalized on the wire,
	// offset_minutes restores the local render on decode (pre-remainder
	// this pin asserted the hard-zeroed 21:00Z normalization).
	assert cx_out.contains('alpha'), 'missing alpha row: ${cx_out}'
	assert cx_out.contains('2024-01-15T12:34:56Z'), 'missing first datetime: ${cx_out}'
	assert cx_out.contains('2025-06-30T23:00:00+02:00'),
		'expected the offset-preserving local render; got: ${cx_out}'
	assert cx_out.contains('2023-12-25T08:15:30.25Z'),
		'expected fractional truncated trailing zero; got: ${cx_out}'
}

// ── #815-adjacent: the SCALAR temporal decode reconstruction ─────────────────
//
// data-bin.md §3.6 gives temporal scalars their own tags — 0x31 date, 0x32
// datetime (§3.6.1, 12 bytes). Decoding one produced a DataDate/DataDateTime,
// and `dataval_to_scalar_type` answered date_type/datetime_type for it — but
// the VALUE arm (`dataval_to_scalar`) had no matching case, so the
// reconstruction fell through to the empty-scalar default: the element came
// back as `[when]`, the instant SILENTLY GONE. Silent loss is the worst decode
// failure; these pin the value onto the reconstruction.
//
// V does not yet WRITE these tags in scalar position (it emits the string tag
// 0x30 — the kind-erasure half, filed as #830), so the wire images here are
// hand-built, which is also what an interop witness looks like: bytes from
// another engine.

// dbin_scalar_frame wraps one tagged scalar payload as a `{when: <value>}`
// CXCol v1 document — the shape another engine's encoder emits.
fn dbin_scalar_frame(tag u8, payload []u8) []u8 {
	mut b := []u8{}
	b << 'CXCol'.bytes()
	b << u8(0x01) // version
	b << u8(0x01) // flags: little-endian
	b << [u8(64), 0, 0, 0] // max_depth u32 LE
	b << u8(0) // reserved
	b << u8(0x50) // map
	b << u8(0x01) // uvarint count = 1
	b << u8(0x30) // string key
	b << u8(0x04)
	b << 'when'.bytes()
	b << tag
	b << payload
	// parse_data_bin takes the FRAMED form: [u32 LE size][payload].
	mut framed := []u8{}
	for i in 0 .. 4 {
		framed << u8((u32(b.len) >> (8 * i)) & 0xFF)
	}
	framed << b
	return framed
}

fn dbin_le64(v i64) []u8 {
	mut p := []u8{}
	for i in 0 .. 8 {
		p << u8((u64(v) >> (8 * i)) & 0xFF)
	}
	return p
}

fn test_scalar_datetime_decodes_with_its_value() {
	// 2026-08-16T12:34:56Z, offset_minutes 0, reserved 0.
	mut p := dbin_le64(i64(1786883696) * i64(1000000000))
	p << [u8(0), 0, 0, 0]
	doc := cx.parse_data_bin(dbin_scalar_frame(0x32, p)) or { panic('decode failed: ${err}') }
	out := cx.emit_cx(doc).trim_space()
	assert out == '[when 2026-08-16T12:34:56Z]', 'scalar datetime lost its value: ${out}'
}

fn test_scalar_datetime_offset_survives_the_reconstruction() {
	// The same instant carried with offset_minutes = -300 (−05:00): the
	// instant is offset-independent, the offset restores the LOCAL render.
	mut p := dbin_le64(i64(1786883696) * i64(1000000000))
	off := u16(u32(i32(-300)))
	p << u8(off & 0xFF)
	p << u8((off >> 8) & 0xFF)
	p << [u8(0), 0]
	doc := cx.parse_data_bin(dbin_scalar_frame(0x32, p)) or { panic('decode failed: ${err}') }
	out := cx.emit_cx(doc).trim_space()
	assert out == '[when 2026-08-16T07:34:56-05:00]', 'offset render lost: ${out}'
}

fn test_scalar_date_decodes_with_its_value() {
	// 0x31: i16 year LE, u8 month, u8 day.
	doc := cx.parse_data_bin(dbin_scalar_frame(0x31, [u8(0xEA), 0x07, 8, 16])) or {
		panic('decode failed: ${err}')
	}
	out := cx.emit_cx(doc).trim_space()
	assert out == '[when 2026-08-16]', 'scalar date lost its value: ${out}'
}

// ── #830 (RULED: 830-1a): V's SCALAR temporal encode ─────────────────────────
//
// `scalar_node_to_dataval` was kind-aware for decimal (0x28) and bigint (0x18)
// only, so date/datetime scalars fell through to the string tag 0x30 and V's
// own data-bin round trip returned a quoted STRING — `[when
// '2026-08-16T12:34:56Z']`. The kind was erased by the transport it was
// supposed to ride. These pin the tag on the wire AND the kind across the
// round trip; the decode half (#815) is pinned above.

// dbin_tag_after_key answers the tag byte following a `{<key>: …}` single-entry
// document's key image — the scalar tag under test.
fn dbin_tag_after_key(b []u8, key string) u8 {
	// [u32 LE size] + 12-byte CXCol header + 0x50 map + uvarint count +
	// 0x30 string-key tag + uvarint len + key bytes → the value tag.
	off := 4 + 12 + 1 + 1 + 1 + 1 + key.len
	assert off < b.len, 'frame too short to hold a ${key} entry'
	return b[off]
}

fn test_scalar_datetime_encodes_as_its_own_tag() {
	doc := cx.parse('[when 2026-08-16T12:34:56Z]') or { panic('parse: ${err}') }
	bytes := cx.emit_data_bin(doc) or { panic('emit: ${err}') }
	assert dbin_tag_after_key(bytes, 'when') == 0x32,
		'a datetime scalar must ride tag 0x32, got 0x${dbin_tag_after_key(bytes, 'when'):02x}'
	doc2 := cx.parse_data_bin(bytes) or { panic('decode: ${err}') }
	out := cx.emit_cx(doc2).trim_space()
	assert out == '[when 2026-08-16T12:34:56Z]', 'datetime kind erased by the round trip: ${out}'
}

fn test_scalar_date_encodes_as_its_own_tag() {
	doc := cx.parse('[on 2026-08-16]') or { panic('parse: ${err}') }
	bytes := cx.emit_data_bin(doc) or { panic('emit: ${err}') }
	assert dbin_tag_after_key(bytes, 'on') == 0x31,
		'a date scalar must ride tag 0x31, got 0x${dbin_tag_after_key(bytes, 'on'):02x}'
	doc2 := cx.parse_data_bin(bytes) or { panic('decode: ${err}') }
	out := cx.emit_cx(doc2).trim_space()
	assert out == '[on 2026-08-16]', 'date kind erased by the round trip: ${out}'
}

fn test_scalar_datetime_offset_rides_the_scalar_wire() {
	// §3.6.1 transport carriage (#807(d)): unix_nanos is UTC-normalized and
	// offset_minutes restores the LOCAL render — on the SCALAR wire, not just
	// the column one.
	doc := cx.parse('[when 2026-08-16T12:34:56-05:00]') or { panic('parse: ${err}') }
	bytes := cx.emit_data_bin(doc) or { panic('emit: ${err}') }
	doc2 := cx.parse_data_bin(bytes) or { panic('decode: ${err}') }
	out := cx.emit_cx(doc2).trim_space()
	assert out == '[when 2026-08-16T12:34:56-05:00]', 'offset render lost on the scalar wire: ${out}'
}

// ── source: vcx/tests/decimal_bigint_semantics_test.v ──
// Tests for I1 row-1 value semantics (stream 11, L40/L42): cross-kind
// numeric equality and ordering are MATHEMATICAL across int/bigint/decimal
// (`bigint 99 = int 99`, `1.10::decimal = 1.1::decimal` — scale is identity,
// value is equality), while decimal/bigint vs STRING is ALWAYS false
// (type-strict — the pre-epoch string arm said decimal "1.10" = string
// "1.10") and decimal vs FLOAT stays unbridged (`[cast]` is the only
// bridge, L44): equality false, ordering CXER0100.

fn run(prog string) string {
	return code.eval_code('', prog, 'cx') or { panic('${err}; prog=${prog}') }
}

// ── mathematical equality within the exact family ────────────────────────────

fn test_decimal_scale_equal_by_value() {
	out := run("[?let [= \$d [row [a::decimal 1.10] [b::decimal 1.1]]] [= \$d/a \$d/b]]")
	assert out.trim_space() == 'true', 'decimal 1.10 must equal 1.1 by value: ${out}'
}

fn test_bigint_equals_int_mathematically() {
	out := run("[?let [= \$d [row [g::bigint 99]]] [= \$d/g 99]]")
	assert out.trim_space() == 'true', 'bigint 99 must equal int 99: ${out}'
}

fn test_decimal_equals_int_mathematically() {
	out := run("[?let [= \$d [row [a::decimal 2.00]]] [= \$d/a 2]]")
	assert out.trim_space() == 'true', 'decimal 2.00 must equal int 2: ${out}'
}

fn test_decimal_not_equal_different_value() {
	out := run("[?let [= \$d [row [a::decimal 1.10] [b::decimal 1.11]]] [= \$d/a \$d/b]]")
	assert out.trim_space() == 'false', '1.10 vs 1.11: ${out}'
}

// ── type-strict walls ─────────────────────────────────────────────────────────

fn test_decimal_never_equals_string() {
	out := run("[?let [= \$d [row [a::decimal 1.10] [s '1.10']]] [= \$d/a \$d/s]]")
	assert out.trim_space() == 'false', 'decimal vs string must be false: ${out}'
}

fn test_bigint_never_equals_string() {
	out := run("[?let [= \$d [row [g::bigint 99] [s '99']]] [= \$d/g \$d/s]]")
	assert out.trim_space() == 'false', 'bigint vs string must be false: ${out}'
}

fn test_decimal_never_equals_float() {
	out := run("[?let [= \$d [row [a::decimal 1.5]]] [= \$d/a 1.5e0]]")
	assert out.trim_space() == 'false', 'decimal vs float is unbridged: ${out}'
}

fn test_decimal_float_ordering_errors() {
	out := run("[?let [= \$d [row [a::decimal 1.5]]] [< \$d/a 1.6e0]]")
	assert out.contains('CXER0100'), 'decimal vs float ordering must error: ${out}'
}

// ── mathematical ordering within the exact family ────────────────────────────

fn test_decimal_ordering() {
	out := run("[?let [= \$d [row [a::decimal 1.05] [b::decimal 1.10]]] [< \$d/a \$d/b]]")
	assert out.trim_space() == 'true', '1.05 < 1.10: ${out}'
}

fn test_decimal_int_ordering() {
	out := run("[?let [= \$d [row [a::decimal 1.99]]] [< \$d/a 2]]")
	assert out.trim_space() == 'true', '1.99 < 2: ${out}'
}

fn test_bigint_ordering_beyond_f64_precision() {
	// Distinct at digit 19 — an f64 round-trip would merge them.
	out := run('[?let [= $d [row [g 99999999999999999998] [h 99999999999999999999]]] [< $d/g $d/h]]')
	assert out.trim_space() == 'true', 'exact bigint ordering: ${out}'
}

fn test_bigint_int_ordering() {
	out := run("[?let [= \$d [row [g::bigint 99]]] [< \$d/g 100]]")
	assert out.trim_space() == 'true', 'bigint 99 < int 100: ${out}'
}

fn test_negative_decimal_ordering() {
	out := run("[?let [= \$d [row [a::decimal -1.10] [b::decimal -1.05]]] [< \$d/a \$d/b]]")
	assert out.trim_space() == 'true', '-1.10 < -1.05: ${out}'
}

// ── L44: exact arithmetic ─────────────────────────────────────────────────────

fn test_decimal_addition_exact_scale_max() {
	// 19.99 + 19.99 = 39.98 exactly; f64 would give 39.980000000000004.
	out := run("[?let [= \$d [row [a::decimal 19.99]]] [+ \$d/a \$d/a]]")
	assert out.contains('39.98'), 'exact add: ${out}'
	assert !out.contains('39.980000'), 'float leak: ${out}'
}

fn test_decimal_sub_preserves_max_scale() {
	// 1.10 − 0.2 = 0.90 (scale max(2,1) = 2 — trailing zero kept).
	out := run("[?let [= \$d [row [a::decimal 1.10] [b::decimal 0.2]]] [- \$d/a \$d/b]]")
	assert out.contains('0.90'), 'sub scale: ${out}'
}

fn test_decimal_mul_scale_adds() {
	// 2 × 19.99 = 39.98 (scale 0+2).
	out := run("[?let [= \$d [row [a::decimal 19.99]]] [* 2 \$d/a]]")
	assert out.contains('39.98'), 'mul: ${out}'
}

fn test_decimal_div_terminating_exact() {
	out := run("[?let [= \$d [row [a::decimal 1.00]]] [/ \$d/a 8]]")
	assert out.contains('0.125'), 'div: ${out}'
}

fn test_decimal_div_non_terminating_errors() {
	out := run("[?let [= \$d [row [a::decimal 1.00]]] [/ \$d/a 3]]")
	assert out.contains('CXER3002'), 'non-terminating must error: ${out}'
}

fn test_decimal_div_by_zero() {
	out := run("[?let [= \$d [row [a::decimal 1.00]]] [/ \$d/a 0]]")
	assert out.contains('CXER0101'), 'div by zero: ${out}'
}

fn test_decimal_plus_float_errors() {
	out := run("[?let [= \$d [row [a::decimal 1.5]]] [+ \$d/a 1.5e0]]")
	assert out.contains('CXER0100'), 'decimal+float must error: ${out}'
}

fn test_bigint_arithmetic_exact() {
	// Successor of an over-i64 value — i64 would overflow, f64 would round.
	out := run('[?let [= $d [row [g 99999999999999999999]]] [+ $d/g 1]]')
	assert out.contains('100000000000000000000'), 'bigint add: ${out}'
}

fn test_bigint_mul_stays_exact() {
	out := run('[?let [= $d [row [g 99999999999999999999]]] [* $d/g 2]]')
	assert out.contains('199999999999999999998'), 'bigint mul: ${out}'
}

fn test_decimal_unary_negate() {
	out := run("[?let [= \$d [row [a::decimal 1.50]]] [- \$d/a]]")
	assert out.contains('-1.50'), 'negate keeps scale: ${out}'
}

// ── L44: casts ────────────────────────────────────────────────────────────────

fn test_cast_string_to_decimal_strict() {
	out := run("[\$cast '1.50' :decimal]")
	assert out.contains('1.50'), 'cast string→decimal: ${out}'
}

fn test_cast_bad_string_to_decimal_errors() {
	out := run("[\$cast 'hello' :decimal]")
	assert out.contains('CXER0290'), 'cast junk→decimal: ${out}'
}

fn test_cast_float_to_decimal_shortest_digits() {
	out := run('[$cast 1.5e0 :decimal]')
	assert out.contains('1.5'), 'cast float→decimal: ${out}'
}

fn test_cast_decimal_to_int_integral_only() {
	ok := run("[?let [= \$d [row [a::decimal 2.00]]] [\$cast \$d/a :int]]")
	assert ok.trim_space() == '2', 'integral decimal→int: ${ok}'
	bad := run("[?let [= \$d [row [a::decimal 2.50]]] [\$cast \$d/a :int]]")
	assert bad.contains('CXER0290'), 'fractional decimal→int must error: ${bad}'
}

fn test_cast_decimal_to_float_lossy_allowed() {
	out := run("[?let [= \$d [row [a::decimal 1.5]]] [\$cast \$d/a :float]]")
	assert out.contains('1.5'), 'decimal→float: ${out}'
}

fn test_cast_string_to_bigint() {
	out := run("[\$cast '99999999999999999999' :bigint]")
	assert out.contains('99999999999999999999'), 'string→bigint: ${out}'
}

// ── row-1 defect tail ─────────────────────────────────────────────────────────

fn test_json_all_decimal_is_exact() {
	// Defect D: the documented EXACT mode was aliased to lossy all-float —
	// 17 significant digits survive now.
	out := run("[?lib 'cx-stdlib/json'] [\$json:parse-with-opts '{\"x\": 0.12345678901234567}' {number-mode: 'all-decimal'}]")
	assert out.contains('0.12345678901234567'), 'all-decimal must be exact: ${out}'
}

fn test_transcendental_over_decimal_is_cxer3002() {
	out := run("[?let [= \$d [row [a::decimal 2.00]]] [\$sqrt \$d/a]]")
	assert out.contains('CXER3002'), 'sqrt(decimal) must refuse with CXER3002: ${out}'
}

// ── source: vcx/tests/duration_period_test.v ──
// Pass-2 Duration/Period type promotion (lexicon [L25]/[L26]).
//
// Duration is an EXACT span ({ns,us,ms,s,m,h,d,w} → i64 ns); Period is a
// CALENDAR span ({mo,y}). Both are first-class ScalarType refinements
// recognized in the data AND program readings, carrying their verbatim CX
// text as the value and rendering bare. This test covers recognition, the
// ::annotation forms, both readings, the binary wire round-trip, and the
// lexing rules (longest-match, whole-token, no mixed family).

// ── Data-reader recognition ──────────────────────────────────────────────────

fn test_data_duration_units() {
	for tok in ['100ms', '1h30m', '90s', '2w', '5d', '250us', '40ns'] {
		s := scalar_of('[t ${tok}]')
		assert s.data_type == .duration_type, '${tok} expected duration, got ${s.data_type}'
		assert (s.value as string) == tok, 'value mismatch for ${tok}'
	}
}

fn test_data_period_units() {
	for tok in ['3mo', '1y', '1y6mo', '18mo'] {
		s := scalar_of('[t ${tok}]')
		assert s.data_type == .period_type, '${tok} expected period, got ${s.data_type}'
	}
}

fn test_data_minutes_vs_months() {
	// `m` is minutes (duration); `mo` is months (period) — longest-match.
	assert scalar_of('[t 5m]').data_type == .duration_type, '5m should be duration'
	assert scalar_of('[t 5mo]').data_type == .period_type, '5mo should be period'
}

fn test_data_non_temporal_stays_text() {
	// Whole-token rule: a trailing non-unit run is NOT a span.
	doc := cx.parse('[t 5mph]') or {
		assert false, '${err}'
		return
	}
	el := doc.elements[0] as cx.Element
	// `5mph` must be a TextNode (or a string scalar), never a duration/period.
	item := el.items[0]
	if item is cx.ScalarNode {
		assert item.data_type != .duration_type && item.data_type != .period_type, '5mph wrongly typed temporal'
	}
}

fn test_data_mixed_family_not_one_literal() {
	// `1y2h` mixes period + duration units → not a single span literal (it
	// becomes Text, not a typed scalar).
	doc := cx.parse('[t 1y2h]') or {
		assert false, '${err}'
		return
	}
	item := (doc.elements[0] as cx.Element).items[0]
	if item is cx.ScalarNode {
		assert item.data_type != .duration_type && item.data_type != .period_type, '1y2h wrongly typed as a span'
	}
}

// ── Explicit annotations ─────────────────────────────────────────────────────

fn test_explicit_duration_period_annotation() {
	assert scalar_of('[t::duration 90m]').data_type == .duration_type, '::duration'
	assert scalar_of('[t::period 2y]').data_type == .period_type, '::period'
}

// ── Binary wire round-trip (the promotion the user asked for) ────────────────

fn test_wire_codec_preserves_duration_period() {
	doc := cx.parse('[a 1h30m]\n[b 1y6mo]') or {
		assert false, '${err}'
		return
	}
	bytes := cx.emit_ast_bin(doc)
	doc2 := cx.bin_to_doc(bytes) or {
		assert false, 'decode: ${err}'
		return
	}
	a := (doc2.elements[0] as cx.Element).items[0] as cx.ScalarNode
	b := (doc2.elements[1] as cx.Element).items[0] as cx.ScalarNode
	assert a.data_type == .duration_type, 'wire lost duration type, got ${a.data_type}'
	assert (a.value as string) == '1h30m', 'wire duration value mismatch'
	assert b.data_type == .period_type, 'wire lost period type, got ${b.data_type}'
	assert (b.value as string) == '1y6mo', 'wire period value mismatch'
}

// ── Program reading ──────────────────────────────────────────────────────────

fn test_program_duration_period_types() {
	dur := code.eval_code('', '2w', 'json') or {
		assert false, '${err}'
		return
	}
	assert dur.contains('"dataType":"duration"'), 'program 2w not duration: ${dur}'
	per := code.eval_code('', '1y6mo', 'json') or {
		assert false, '${err}'
		return
	}
	assert per.contains('"dataType":"period"'), 'program 1y6mo not period: ${per}'
}

fn test_program_renders_bare() {
	for tok in ['100ms', '1h30m', '2w', '5d', '3mo', '1y6mo'] {
		out := code.eval_code('', tok, 'cx') or {
			assert false, '${err}'
			return
		}
		assert out.trim_space() == tok, '${tok} should render bare, got ${out}'
	}
}

fn test_program_invalid_temporal_is_error() {
	// `5mph` is not a valid temporal literal: the PROGRAM reader (lexer/parser)
	// rejects it. Assert at that layer — the program reader is unchanged.
	if _ := cx.parse_program('5mph') {
		assert false, 'expected lex/parse error for 5mph in the program reader'
	}
	// NOTE: `code.eval_code('', '5mph', 'cx')` no longer errors — `5mph` is a
	// valid DATA scalar, and per code.md §1.3 ("a pure-data resource evaluates to
	// itself") eval now falls back to the data reading when the program parse
	// fails (#11). So eval_code returns the scalar `5mph` (data evaluating to
	// itself), NOT a lex error. The malformed-temporal rejection lives in the
	// program reader (asserted above), not at the eval boundary.
	out := code.eval_code('', '5mph', 'cx') or {
		assert false, '5mph should evaluate to itself via the data fallback, got error: ${err}'
		return
	}
	assert out.trim_space() == '5mph', '5mph data-fallback should round-trip, got: ${out}'
}

// ── XML ISO-8601 image (lexicon [L25]/[L26]) ─────────────────────────────────

fn test_cx_to_xml_iso_image() {
	doc := cx.parse('[timeout 90m]\n[span 1y6mo]\n[wk 2w]\n[sub 500ms]') or {
		assert false, '${err}'
		return
	}
	xml := cx.emit_xml(doc)
	// Duration/period bodies carry the ISO 8601 image inside a <cx:T> carrier.
	assert xml.contains('<cx:duration>PT1H30M</cx:duration>'), '90m→ISO: ${xml}'
	assert xml.contains('<cx:period>P1Y6M</cx:period>'), '1y6mo→ISO: ${xml}'
	assert xml.contains('<cx:duration>P2W</cx:duration>'), '2w→ISO: ${xml}'
	assert xml.contains('<cx:duration>PT0.5S</cx:duration>'), '500ms→ISO: ${xml}'
}

fn test_xml_to_cx_round_trip_value_stable() {
	src := '[combo 1h30m]\n[span 1y6mo]\n[sub 500ms]\n[nano 40ns]'
	doc := cx.parse(src) or {
		assert false, '${err}'
		return
	}
	xml := cx.emit_xml(doc)
	doc2 := cx.parse_xml(xml) or {
		assert false, 'xml parse: ${err}'
		return
	}
	// Types survive; values are value-stable (already canonical here).
	c := (doc2.elements[0] as cx.Element).items[0] as cx.ScalarNode
	assert c.data_type == .duration_type && (c.value as string) == '1h30m', 'combo: ${c.value}'
	s := (doc2.elements[1] as cx.Element).items[0] as cx.ScalarNode
	assert s.data_type == .period_type && (s.value as string) == '1y6mo', 'span: ${s.value}'
	n := (doc2.elements[3] as cx.Element).items[0] as cx.ScalarNode
	assert n.data_type == .duration_type && (n.value as string) == '40ns', 'nano: ${n.value}'
}

fn test_iso_helpers_round_trip() {
	assert cx.duration_cx_to_iso('1h30m') or { '' } == 'PT1H30M'
	assert cx.duration_cx_to_iso('2w') or { '' } == 'P2W'
	assert cx.duration_cx_to_iso('10d') or { '' } == 'P10D'
	assert cx.period_cx_to_iso('1y6mo') or { '' } == 'P1Y6M'
	assert cx.iso_to_duration_cx('PT1H30M') or { '' } == '1h30m'
	assert cx.iso_to_period_cx('P1Y6M') or { '' } == '1y6mo'
	// value-stable canonicalization: 90m → ISO → 1h30m
	assert cx.iso_to_duration_cx(cx.duration_cx_to_iso('90m') or { '' }) or { '' } == '1h30m'
}

// ── Datetime range stepped by extended duration unit ─────────────────────────

fn test_datetime_range_by_day_unit() {
	out := code.eval_code('', '[\$range 2024-01-01T00:00:00Z 2024-01-03T00:00:00Z 1d]', 'cx') or {
		assert false, '${err}'
		return
	}
	// lo, lo+1d, lo+2d (inclusive) → three datetimes.
	assert out.contains('2024-01-02T00:00:00Z'), 'range by 1d missing middle step: ${out}'
}

// ── source: vcx/tests/numerics_test.v ──
// Tests for v3.4 numeric grammar changes:
//   - Underscores in integer/float/hex literals (additive).
//   - Leading-zero rejection in auto-typed integers (BREAKING).
//
// Spec: spec/grammar.ebnf [20a]/[20b]/[20c], spec/policies.md §1.7.
// ── Underscores accepted ─────────────────────────────────────────────────────

fn test_int_with_underscores() {
	doc := cx.parse('[count 1_000_000]') or { panic(err) }
	root := doc.root() or { panic('no root') }
	s := root.scalar() or { panic('not scalar') }
	if s is i64 { assert s == 1000000 } else { assert false, 'expected i64' }
}

fn test_int_many_underscores() {
	doc := cx.parse('[v 1_2_3_4_5]') or { panic(err) }
	root := doc.root() or { panic('no root') }
	s := root.scalar() or { panic('not scalar') }
	if s is i64 { assert s == 12345 } else { assert false, 'expected i64' }
}

fn test_negative_int_with_underscores() {
	doc := cx.parse('[v -1_000]') or { panic(err) }
	root := doc.root() or { panic('no root') }
	s := root.scalar() or { panic('not scalar') }
	if s is i64 { assert s == -1000 } else { assert false, 'expected i64' }
}

fn test_fraction_with_underscores_is_decimal() {
	// I1 2b: a bare fixed-point fraction is a DECIMAL (underscores strip).
	doc := cx.parse('[v 1.234_567]') or { panic(err) }
	root := doc.root() or { panic('no root') }
	s := root.scalar() or { panic('not scalar') }
	if s is string { assert s == '1.234567' } else { assert false, 'expected decimal image' }
}

fn test_hex_with_underscores() {
	doc := cx.parse('[v 0xDEAD_BEEF]') or { panic(err) }
	root := doc.root() or { panic('no root') }
	s := root.scalar() or { panic('not scalar') }
	if s is i64 { assert s == 0xDEADBEEF } else { assert false, 'expected i64' }
}

fn test_attribute_int_with_underscores() {
	doc := cx.parse('[item count=1_000]') or { panic(err) }
	root := doc.root() or { panic('no root') }
	assert root.attr('count') == '1000', 'unexpected: ${root.attr("count")}'
}

// ── Underscores rejected (malformed) ─────────────────────────────────────────

fn test_leading_underscore_falls_through_to_text() {
	// `_1000` is not a valid number; auto-types as Text.
	doc := cx.parse('[v _1000]') or { panic(err) }
	root := doc.root() or { panic('no root') }
	if _ := root.scalar() {
		assert false, 'expected text, got scalar'
	}
}

fn test_trailing_underscore_falls_through_to_text() {
	doc := cx.parse('[v 1000_]') or { panic(err) }
	root := doc.root() or { panic('no root') }
	if _ := root.scalar() {
		assert false, 'expected text, got scalar'
	}
}

fn test_doubled_underscore_falls_through_to_text() {
	doc := cx.parse('[v 1__000]') or { panic(err) }
	root := doc.root() or { panic('no root') }
	if _ := root.scalar() {
		assert false, 'expected text, got scalar'
	}
}

// ── Leading-zero tightening (BREAKING in v3.4) ───────────────────────────────

fn test_leading_zero_zip_falls_through_to_text() {
	// '02134' is no longer auto-typed as int 2134. It's Text "02134".
	doc := cx.parse('[zip 02134]') or { panic(err) }
	root := doc.root() or { panic('no root') }
	if _ := root.scalar() {
		assert false, 'expected text, got scalar — leading-zero tightening failed'
	}
}

fn test_leading_zero_multidigit_falls_through() {
	doc := cx.parse('[v 007]') or { panic(err) }
	root := doc.root() or { panic('no root') }
	if _ := root.scalar() {
		assert false, 'expected text, got scalar'
	}
}

fn test_plain_zero_still_int() {
	// The literal '0' is fine — it's the sole exception.
	doc := cx.parse('[v 0]') or { panic(err) }
	root := doc.root() or { panic('no root') }
	s := root.scalar() or { panic('not scalar') }
	if s is i64 { assert s == 0 } else { assert false, 'expected i64' }
}

fn test_negative_zero_int_still_int() {
	doc := cx.parse('[v -0]') or { panic(err) }
	root := doc.root() or { panic('no root') }
	s := root.scalar() or { panic('not scalar') }
	if s is i64 { assert s == 0 } else { assert false, 'expected i64' }
}

fn test_hex_zero_still_int() {
	// Hex is exempt — '0x...' is unambiguous.
	doc := cx.parse('[v 0x42]') or { panic(err) }
	root := doc.root() or { panic('no root') }
	s := root.scalar() or { panic('not scalar') }
	if s is i64 { assert s == 0x42 } else { assert false, 'expected i64' }
}

fn test_explicit_int_annotation_accepts_leading_zero() {
	// :int annotation overrides the auto-typing rule. The user has
	// declared this is an integer; respect the value.
	doc := cx.parse('[v::int 02134]') or { panic(err) }
	root := doc.root() or { panic('no root') }
	s := root.scalar() or { panic('not scalar') }
	if s is i64 { assert s == 2134 } else { assert false, 'expected i64' }
}

